  #{taskId}

DELETE mt FROM project_milestone_task mt
INNER JOIN project_milestone m ON m.workspace_id = mt.workspace_id AND m.id = mt.milestone_id
WHERE mt.workspace_id = #{workspaceId} AND m.req_id = #{reqId}

DELETE l FROM project_milestone_log l
INNER JOIN project_milestone m ON m.workspace_id = l.workspace_id AND m.id = l.milestone_id
WHERE l.workspace_id = #{workspaceId} AND m.req_id = #{reqId}
